-- 2026-07-26 user_weekly_points 포인트 복구 — STEP 20: 복구 계획 적재 — 청크 7/8
--
-- 원인: db/migrations/2026-07-25_point_resolver_sot.sql §2 가 2026-07-25T04:52:05.480492Z 에
--   운영 DB 에서 실행되어, checks_migrated=true 이면서 활성 process_point_awards 가 없는
--   user_weekly_points 행을 전부 0 으로 덮었다(PMS·레거시 이관 포인트 소멸).
-- 복구 원천: public.legacy_point_ledger 재구성 — 11508행 / 629명 / ΣA 449474 · Σadv 30810 · Σpen 18891
--
-- ⚠ 실행 순서: 10 → 20(001~008) → 30 → 40.  롤백은 99.
-- ⚠ 현재 단계: 20-007 (staging 적재만 · user_weekly_points 무접촉)

-- 이 청크: 1500행 · ΣA 4308 · Σadv 1721 · Σpen 1439
-- 멱등: PK(uwp_id) ON CONFLICT DO UPDATE — 같은 청크를 몇 번 실행해도 행이 늘지 않고 값도 동일하다.
-- 순서 무관: 청크는 어떤 순서로 실행해도 되며, 전부 적재된 뒤 STEP 30 이 완전성을 검증한다.

begin;

on conflict (uwp_id) do update
   set user_id = excluded.user_id,
       week_start_date = excluded.week_start_date,
       points = excluded.points,
       advantages = excluded.advantages,
       penalty = excluded.penalty,
       pre_points = excluded.pre_points,
       pre_advantages = excluded.pre_advantages,
       pre_penalty = excluded.pre_penalty,
       chunk_no = excluded.chunk_no,
       loaded_at = now();

do $$
declare n int; s_a bigint; s_adv bigint; s_pen bigint; tot int;
begin
  select count(*), sum(points), sum(advantages), sum(penalty)
    into n, s_a, s_adv, s_pen from public.uwp_recovery_staging_20260726 where chunk_no = 7;
  select count(*) into tot from public.uwp_recovery_staging_20260726;
  raise notice '[chunk 7/8] 적재 %행 · ΣA % · Σadv % · Σpen % | staging 누적 %/11508행', n, s_a, s_adv, s_pen, tot;
  if n     <> 1500 then raise exception '청크 7 행수 % (기대 1500)', n; end if;
  if s_a   <> 4308    then raise exception '청크 7 ΣA % (기대 4308)', s_a; end if;
  if s_adv <> 1721  then raise exception '청크 7 Σadv % (기대 1721)', s_adv; end if;
  if s_pen <> 1439  then raise exception '청크 7 Σpen % (기대 1439)', s_pen; end if;
end $$;

commit;

